/**
 * FRONTEND EXERCISE, Part B: see docs/learn/07-frontend.md, section "Exercise".
 * Run with: npm run test:exercises   (they fail until you do the exercise; do not edit this file)
 */
import { screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it, vi } from 'vitest';
import { ApiError, NetworkError } from '../api/client';
import { retrying } from '../api/retry';
import { fakeApi, json } from '../test/fakeApi';
import { placedOrder, putMugInCart } from '../test/shopping';

function apiError(status: number, retryAfterSeconds: number | null = null) {
  return new ApiError(status, 'Error', 'failed', null, {}, retryAfterSeconds, {});
}

/** A task that fails with the given errors in turn, then succeeds. */
function failing(...errors: Error[]) {
  return vi.fn(async () => {
    const next = errors.shift();
    if (next) {
      throw next;
    }
    return 'done';
  });
}

describe('Part B: retrying()', () => {
  it('runs the task once when it works', async () => {
    const task = failing();

    await expect(retrying(task)).resolves.toBe('done');
    expect(task).toHaveBeenCalledTimes(1);
  });

  it('retries a NetworkError, waiting longer each time (exponential backoff)', async () => {
    const task = failing(new NetworkError('offline'), new NetworkError('offline'));
    const sleep = vi.fn(async () => {});

    await expect(retrying(task, { attempts: 3, baseDelayMs: 100, sleep })).resolves.toBe('done');
    expect(task).toHaveBeenCalledTimes(3);
    expect(sleep.mock.calls).toEqual([[100], [200]]);
  });

  it('retries 502, 503 and 504, and waits as long as Retry-After says', async () => {
    const task = failing(apiError(503, 2), apiError(502), apiError(504));
    const sleep = vi.fn(async () => {});

    await expect(retrying(task, { attempts: 4, baseDelayMs: 100, sleep })).resolves.toBe('done');
    expect(sleep.mock.calls).toEqual([[2000], [200], [400]]);
  });

  it('never retries other errors: the same request would fail the same way', async () => {
    for (const status of [400, 401, 404, 409, 422, 429]) {
      const task = failing(apiError(status));

      await expect(retrying(task, { sleep: async () => {} })).rejects.toMatchObject({ status });
      expect(task).toHaveBeenCalledTimes(1);
    }
  });

  it('gives up after the last attempt and throws its error', async () => {
    const task = failing(new NetworkError('1'), new NetworkError('2'), new NetworkError('3'));

    await expect(retrying(task, { attempts: 3, sleep: async () => {} })).rejects.toThrow('3');
    expect(task).toHaveBeenCalledTimes(3);
  });

  it('checkout survives a dropped connection without a second click, and without a second order', async () => {
    let calls = 0;
    const server = fakeApi().on('POST /orders', () => {
      calls += 1;
      if (calls === 1) {
        throw new TypeError('Failed to fetch'); // the first attempt gets no answer at all
      }
      return json(placedOrder, 201);
    });
    await putMugInCart(server);

    await userEvent.click(screen.getByRole('button', { name: 'Place order' }));

    expect(await screen.findByText(/Order #99 was placed/, {}, { timeout: 5000 })).toBeInTheDocument();
    const [first, second] = server.callsTo('POST /orders');
    // The first request MAY have reached the server before the connection dropped. The same key
    // means the server returns that order instead of creating a second one.
    expect(second.headers.get('Idempotency-Key')).toBe(first.headers.get('Idempotency-Key'));
  });
});
